from typing import Literal

from pydantic import BaseModel, Field

# All IDs are restricted to safe characters so they can be written to CSV as-is.

# Participant ID passed in from the survey link (e.g. Qualtrics ResponseID).
Pid = Field(pattern=r"^[A-Za-z0-9_-]{1,100}$")
# Random ID generated by the browser for each event / submission. If a request is
# retried after a network problem, the same ID is sent again and the duplicate is ignored.
RequestId = Field(pattern=r"^[A-Za-z0-9-]{8,64}$")
SafeKey = Field(pattern=r"^[A-Za-z0-9_-]{1,100}$")

Action = Literal["like", "unlike", "follow", "unfollow", "save", "unsave", "share", "unshare"]


class PostData(BaseModel):
    postId: str
    profileName: str
    imageUrl: str
    blockNumber: int
    postPosition: int


class PostsResponse(BaseModel):
    posts: list[PostData]


class EngagementEvent(BaseModel):
    eventId: str = RequestId
    pid: str = Pid
    postId: str = SafeKey
    blockNumber: int = Field(ge=1, le=1000)
    postPosition: int = Field(ge=1, le=1000)
    action: Action


class ThemeLocalizationEntry(BaseModel):
    theme: str = SafeKey
    post1: bool
    post2: bool
    post3: bool
    post4: bool
    post5: bool


class BlockSurveySubmission(BaseModel):
    submissionId: str = RequestId
    pid: str = Pid
    blockNumber: int = Field(ge=1, le=1000)
    themes: dict[str, bool]
    localizations: list[ThemeLocalizationEntry]
